S=list(T.keys())
res=[]
for ns in [3,4]:
  for sc in itertools.combinations(S,ns):
    for nc in [1,2]:
      for cc in itertools.combinations(S,nc):
        cols=[T[k] for k in sc]+[T[k]*A**2 for k in cc]
